"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[3531],{43531:a=>{a.exports=JSON.parse('{"slug":"vvod-izhs-2026-upal-na-21-procent-eskrou","locale":"ru","title":"Ввод частных домов за 9 месяцев упал на 21%, до минимума с 2021 года","description":"В январе–сентябре 2026 года ввод частных домов упал на 21%, до 41,4 млн кв. м. Как эскроу и дорогие кредиты меняют строительство домов.","blocks":[{"id":"b001","kind":"paragraph","text":"За 9 месяцев 2026 года в России ввели 66,3 млн кв. м жилья, на 13,4% меньше, чем годом раньше. Всё падение пришлось на частные дома: их ввели 41,4 млн кв. м, на 21% меньше. Последний раз меньше было в 2021 году, 35,1 млн кв. м. Многоквартирных домов, наоборот, сдали на 3% больше, 24,9 млн кв. м. Доля частных домов в общем вводе снизилась за год на 5,9 процентного пункта, до 62,5%."},{"id":"b002","kind":"paragraph","text":"Среди 5 регионов, где строят больше всего, ввод сильнее всего упал в Подмосковье и на Кубани. В Подмосковье за 9 месяцев сдали 6,9 млн кв. м жилья, на 29,5% меньше, в Краснодарском крае 3,1 млн, на 31,7% меньше. Ведущий аналитик ЦИАН Елена Бобровская называет общие причины: дорогие кредиты и стагнацию экономики. Для частных домов к ним добавились переход на эскроу и конец эффекта \xabдачной амнистии\xbb. По оценке Вячеслава Астафьева из Starkwood, бюджеты проектов за год выросли на 10–15%, быстрее инфляции."},{"id":"b003","kind":"paragraph","text":"Представим портного, которому заказчик кладёт деньги в банк, а забрать их можно только после примерки готового костюма. Ткань, нитки и зарплату помощнику портной оплачивает сам или в кредит. Крупному ателье это по силам, маленькой мастерской нет. Так работает эскроу. С 1 марта 2025 года подрядчик, который строит дом по льготной ипотеке, получает деньги только так: в течение 5 рабочих дней после регистрации дома. Сейчас с эскроу для частных домов работают около 1,5 тыс. подрядчиков."},{"id":"b004","kind":"paragraph","text":"Второй фактор статистический. Ввод частных домов считают по регистрации, и долгое время его поднимала \xabдачная амнистия\xbb: люди оформляли дома, построенные раньше. Она давала до 25–30% ввода частных домов. Упрощённую регистрацию продлили до 2031 года, но операционный директор \xabМ9 девелопмент\xbb Антон Минеджян считает её эффект почти исчерпанным. Часть падения показывает не то, что стали меньше строить, а то, что старые дома уже оформлены."},{"id":"b005","kind":"paragraph","text":"В сентябре ввод частных домов впервые в 2026 году вырос, на 4%, до 5,3 млн кв. м. В том же месяце выдачи ипотеки на частные дома выросли к августу на 42%, до почти 17 тыс. Семьи спешили до 1 октября: с этого дня ставка семейной ипотеки для семьи с одним ребёнком выросла с 6% до 10–12%. Если кредиты взяты на строительство, на вводе они скажутся позже."},{"id":"b006","kind":"paragraph","text":"Минстрой ждёт, что за 2026 год введут 87,7 млн кв. м жилья, примерно на 20% меньше, чем в 2025-м, а загородного почти на 25% меньше. Это хуже итога 9 месяцев, то есть к концу года спад должен усилиться. Для тех, кто собирается строить дом по льготной ипотеке, выбор подрядчиков ограничен теми, кто прошёл проверку банка, а смета растёт быстрее цен. Крупные застройщики могли бы заменить мелкие бригады, но посёлку нужны дороги и сети ещё до первых продаж."},{"id":"b007","kind":"heading","text":"Насколько упал ввод частных домов в 2026 году?"},{"id":"b008","kind":"paragraph","text":"В январе–сентябре 2026 года ввели 41,4 млн кв. м частных домов, на 21% меньше, чем годом раньше. Меньше было только в 2021 году, 35,1 млн кв. м. Весь ввод жилья снизился на 13%, до 66,3 млн кв. м."},{"id":"b009","kind":"heading","text":"Как эскроу работает при строительстве частного дома?"},{"id":"b010","kind":"paragraph","text":"Деньги заёмщика лежат на счёте в банке, и подрядчик получает их в течение 5 рабочих дней после регистрации дома. Строит он на свои или заёмные средства. С 1 марта 2025 года это обязательно, если дом строит подрядчик по льготной ипотеке."},{"id":"b011","kind":"heading","text":"Восстанавливается ли ввод частных домов?"},{"id":"b012","kind":"paragraph","text":"В сентябре ввод вырос на 4% к прошлому году, впервые в 2026 году. Но Минстрой ждёт падения загородного жилья за год почти на 25%, сильнее, чем за 9 месяцев. С 1 октября семейная ипотека для семей с одним ребёнком подорожала до 10–12%, и спрос на дома может снизиться."}],"sources":[{"label":"Метром не вышли. Ввод ИЖС в России снизился на 21%","url":"https://www.kommersant.ru/doc/9042244"},{"label":"Ввод жилья в России за три квартала снизился на 13,4%","url":"https://1prime.ru/20261019/rosstat-874384990.html"},{"label":"В сентябре ввод ИЖС впервые в 2026-м превысил уровень прошлого года","url":"https://finance.mail.ru/article/v-sentyabre-vvod-izhs-vpervyie-v-2026-m-prevyisil-uroven-proshlogo-goda-69233224/"},{"label":"Ввод жилья в России сократился за три квартала на 13%","url":"https://realty.ria.ru/20261019/vvod-2125392621.html"},{"label":"Изменения в 186-ФЗ — что важно знать участникам ипотечного рынка ИЖС","url":"https://harant.ru/blog/bankovskie-voprosy-finansy/izmeneniya-v-186-fz-chto-vazhno-znat-uchastnikam-ipotechnogo-rynka-izhs/"}],"sourceBodySha256":"bcf9ff6044973cdce07fbb0598c5351b940a456fbe7c887a552863309c39870a"}')}}]);